/** Semantic-preserving runtime wrappers. No hard-link emulation or argument rewriting. */
export function hardlinkWrappers() {
  const script = [
    '#!/system/bin/sh',
    '# generated by dsh-kxxy build-runtime.mjs — do not edit',
    'd=${0%/*}',
    'exec "$d/coreutils" --coreutils-prog=ln "$@"',
    '',
  ].join('\n');
  return [{ path: 'bin/ln', data: Buffer.from(script, 'utf8'), mode: 0o755 }];
}

/** The guard invokes native rsync unchanged, including --link-dest and --delete. */
export function rsyncWrappers() {
  const script = [
    '#!/system/bin/sh',
    '# generated by dsh-kxxy build-runtime.mjs — do not edit',
    'd=${0%/*}',
    'case "$d" in /*) ;; *) d=$PWD/$d ;; esac',
    'root=$(cd "$d/.." 2>/dev/null && pwd) || exit 127',
    'exec "$root/bin/python" "$root/libexec/kxxy-tools/kxxy-rsync.py" "$root/bin/rsync" "$@"',
    '',
  ].join('\n');
  return [{ path: 'bin/kxxy-rsync', data: Buffer.from(script, 'utf8'), mode: 0o755 }];
}
